"""Convert between integers 1..3999 and canonical upper-case Roman numerals."""
import re

_VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

_CANONICAL = re.compile(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})")


def to_roman(n):
    """Standard numeral for n, which must be an integer from 1 to 3999."""
    if not 1 <= n <= 3999:
        raise ValueError(f"number out of range 1..3999: {n}")
    parts = []
    for value, numeral in _VALUES:
        count, n = divmod(n, value)
        parts.append(numeral * count)
    return "".join(parts)


def from_roman(s):
    """Integer for a canonical upper-case numeral, the exact form to_roman produces."""
    if not s or _CANONICAL.fullmatch(s) is None:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    total = 0
    rest = s
    for value, numeral in _VALUES:
        while rest.startswith(numeral):
            total += value
            rest = rest[len(numeral):]
    if to_roman(total) != s:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    return total

